 "theme":   { "fr": "Bibliothèques — extension des horaires", "nl": "Bibliotheken — uitbreiding van de openingsuren", "en": "Libraries — extended opening hours" },
 "matiere": { "key": "culture", "fr": "Culture", "nl": "Cultuur", "en": "Culture" },
 "titre": {
  "fr": "Toronto porte à 67 le nombre de bibliothèques ouvertes sept jours sur sept et recrute 60 agents",
  "nl": "Toronto brengt het aantal bibliotheken dat zeven dagen per week open is op 67 en werft 60 medewerkers aan",
  "en": "Toronto takes the number of libraries open seven days a week to 67 and hires 60 staff"
 },
